LANGUAGES=('es','de','fr')
EXTRA={code:{} for code in LANGUAGES}
for index,code in enumerate(LANGUAGES):
    EXTRA[code].update({'character_'+key:names[index] for key,names in NAMES.items()})
    EXTRA[code].update({key:values[index] for key,values in TEXT.items()})
